package com.wizzadrds.theworldremembers.voice;
import com.mojang.serialization.*; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.*; import java.util.*;
public final class VoiceProfileManager extends SavedData {private final Map<UUID,VoiceProfile> profiles=new HashMap<>(); private static final Codec<VoiceTemperament>T=Codec.STRING.xmap(VoiceTemperament::valueOf,Enum::name); private static final Codec<VoiceProfile>P=RecordCodecBuilder.create(i->i.group(Codec.STRING.fieldOf("language").forGetter(VoiceProfile::language),Codec.STRING.fieldOf("model").forGetter(VoiceProfile::model),T.fieldOf("temperament").forGetter(VoiceProfile::temperament),Codec.INT.fieldOf("pitch").forGetter(VoiceProfile::pitch),Codec.INT.fieldOf("rate").forGetter(VoiceProfile::rate),Codec.INT.fieldOf("expressiveness").forGetter(VoiceProfile::expressiveness)).apply(i,VoiceProfile::new)); private static final Codec<VoiceProfileManager>C=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),P).xmap(m->{var x=new VoiceProfileManager();x.profiles.putAll(m);return x;},x->x.profiles); private static final SavedDataType<VoiceProfileManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","voice_profiles"),VoiceProfileManager::new,C,null); public static VoiceProfileManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new VoiceProfileManager():l.getDataStorage().computeIfAbsent(TYPE);} public VoiceProfile get(UUID id){return profiles.get(id);} public void set(UUID id,VoiceProfile p){profiles.put(id,p);setDirty();} public int size(){return profiles.size();}}
